 return `<div class="layout">${P('Mission / expedition decision',C('Expedition repair dilemma','Known ship damage and permitted local options',true)+N('Persistent consequences','Choices may affect the ship, knowledge, resources and political history. This is an authored fictional scenario, not a discovered campaign event.')+table(['Approach','Known consequence','Uncertainty'],[['Use carried supplies','Finite reserve cost','May be insufficient'],['Request local assistance','Requires lawful contact','Response not guaranteed'],['Continue cautiously','Damage retained','Risk depends on capability']])+future())}${P('Review choice',field('Approach','Use carried supplies',['Use carried supplies','Request assistance','Defer decision'])+N('Policy is consequential','Non-interference is not a universal hard action block. No guaranteed repair ceiling or reward is approved.')+B('Review mission choice','','primary',true))}</div>`;
