 if(id==='colony-dispute'){main=N('Competing deployments paused','Neither side gains ownership from command-processing order. Settlers and equipment remain aboard.','error')+C('Known rival claim','Only legally observed parties are represented')+rows(['Deployment','Paused'],['Possible responses','Withdraw · negotiate · military action'],['Dispute lifecycle','Open']);aside=B('Discuss claim','treaty','primary')+B('Withdraw expedition','','quiet',true);}
 if(id==='blockade'){main=planet()+tabs([['Orbit','blockade'],['Ground','invasion'],['Occupation','occupation']])+C('Planet-specific orbital operation','Orbital control does not transfer sovereignty',true)+field('Strategic objective','Blockade selected planet',['Blockade selected planet','Demand surrender','Attempt contested landing'])+N('Known risk only','Hostile ships elsewhere in the system do not automatically blockade every planet. Contested landings are possible, with losses.');aside=rows(['Space control','Separate from ground'],['Ground forces','Actual committed force'],['Surrender','Not guaranteed'])+B('Ground campaign concept','invasion');}
 if(id==='invasion'){main=C('Abstract planetary campaign','Persistent weekly strategic order · no tile battle',true)+field('Approach','Deliberate advance',['Deliberate advance','Rapid assault','Evacuation'])+field('Bombardment policy','Restrained',['No bombardment','Restrained','Destructive'])+table(['Campaign factor','Authority required'],[['Forces / readiness','Recruitment from actual populations'],['Supply / access','Finite and contested'],['Civilian / infrastructure risk','Estimated, never guaranteed']])+N('Forces persist when orbit is lost','No automatic deletion, teleporting evacuation or ownership from bombardment.');aside=B('Occupation concept','occupation','primary')+N('Open thresholds','Strength, duration, surrender and loss models require further design.');}
 if(id==='occupation'){main=C('Occupation / integration','Ground control and public legitimacy are distinct',true)+field('Standing administration','Proposed policy review',['Proposed policy review','Local autonomy','Security administration'])+table(['Record','Persistent distinction'],[['Government control','One controlling government per planet'],['Population identity','Retained'],['Organised resistance','May continue'],['Liberation','Political history remains']])+N('No instant loyalty','Surrender or conquest does not complete integration. Quantitative occupation rules remain open.');aside=B('Population policy','politics','primary')+N('Future integration','Existing population-politics foundation does not itself implement conquest or liberation.');}
