function battle(){
 if(id==='battle-review')return modalPage('Commit orders for round2?',table(['Owned fleet','Standing','Unsent replacement'],[['Expedition','Maintain distance','Screen · Contact A'],['Border patrol','Hold','Retain standing']])+N('One joint round','Commit once. Individual ships choose legal targets automatically. Opponent orders/readiness remain private.'),'battle-orders','Commit round (concept)','battle-waiting');
 const complete=['battle-aftermath','battle-fresh','battle-no-survivors'].includes(id),hidden=['battle-hidden','battle-mutual'].includes(id)||complete,result=['battle-result','battle-reveal','battle-replay'].includes(id),waiting=id==='battle-waiting';
 let rail=C('Expedition fleet','Selected · 3 own ships',true,'battle-orders')+C('Border patrol','Separate strategic command unit',false,'fleet')+`<h3>Visible hostiles</h3>`+(hidden?N('None visible','No count, type or location is disclosed.'):C('Observed contact A','Permitted visible fleet only',false,'contact'))+`<div class="actions">${B('Other battles','battle-lobby')}</div>`;
 if(id==='battle-lobby')return `<div class="layout">${P('Owned encounter selection',C('Bajor / encounter in progress','Your participating Expedition fleet · round2',true,'battle-orders')+C('Other owned engagement','Readiness exposed only by current host status',false,'battle-orders')+N('Whole-batch boundary','Aftermath confirmation is available only when the authoritative whole batch is ready. No hidden participants are listed.'))}${P('Batch status',B('Resume selected battle','battle-orders','primary')+B('Aftermath review','battle-aftermath')+N('No double confirmation','Resolving or viewing a report does not apply consequences again.'))}</div>`;
 if(id==='battle-no-survivors')rail=C('Owned losses','No survivors in this encounter',true)+B('Other owned encounters','battle-lobby');
 let view=`<div class="battle-view"><div class="projection"><img src="assets/exploration-cruiser.png" alt="Owned original provisional cruiser projection"><span class="own-label">Expedition fleet</span>${hidden?'':`<svg class="contact-diamond" viewBox="0 0 200 100"><path d="M12 50L90 10 188 50 90 90Z M12 50H188M90 10V90" fill="none" stroke="#efb16b" stroke-width="2"/></svg><span class="contact-label">Observed contact A</span>`}</div><div class="viewer-tools"><button data-orbit="-8">Orbit ↶</button><button data-orbit="0">Reset view</button><button data-orbit="8">Orbit ↷</button></div><div class="range-label">${complete?'BATTLE COMPLETE · RETAINED SURVIVORS':hidden?'NO VISIBLE TARGET':'DISTANT · OWN FACING FORE'}<br><span class="muted small">Illustrative projection · no physical steering</span></div></div>`;
 if(id==='battle-no-survivors')view='<div class="battle-view"><div class="range-label">NO OWNED SURVIVORS<br>Losses retained · no movement orders</div></div>';
 let report=hidden?N('Maintain your chosen plan','No visible enemy does not grant a free Screen order or disclose a concealed force.'):rows(['Round boundary',result?'Round1 resolved / round2 opens':'Round2 planning'],['Own selected hull','132 / 220'],['Torpedoes','0 / 12']);
 if(result)report=`<div class="report"><b>${id==='battle-reveal'?'Round1 complete / visibility updated':'Round1 resolved'}</b><p>Your hull loss25 · observed destruction0 · own recorded shots0.</p><p>Only the filtered report supplies reveal, fallback and defensive events.</p><p id="replay-step">Replay event1 /3 · illustrative observation</p>${id==='battle-replay'?'<div class="actions"><button data-playback>Play</button><button data-replay>Next event</button><select data-speed aria-label="Playback speed"><option value="1">1×</option><option value="2">2×</option><option value="4">4×</option></select><button data-go="battle-result">Skip to report</button></div>':''}</div>`;
 if(id==='battle-mutual')report=N('No legal offensive targets in round1','Maneuver-only round. No nonexistent shot spends ammunition. It counts within the normal three-round cap.');
 if(complete)report=N('Retained consequences','Hull, shields and finite magazines persist. Routes are stopped; no automatic refill or resumption.');
 let dock='';
 if(id==='battle-inspect')dock=C('Cruiser 1','Owned ship selected for inspection',true)+stock()+N('Ship-relative sectors','Camera orbit does not rotate shield-sector meanings.')+B('Fleet orders','battle-orders');
 else if(result||id==='battle-mutual')dock=C('Round1 resolved','Own standing intent retained; plan the next round explicitly',true)+stock()+N('Filtered results only','No future opposing orders or private magazines appear in the report or replay.')+B('Plan next round','battle-orders','secondary');
 else if(waiting)dock=N('Your order accepted','Own receipt retained. Waiting for authoritative resolution.','success')+C('Committed: Screen','Own selected fleet · Contact A preference')+B('Commit round','','primary',true)+N('Privacy','No opposing readiness counter or commitment animation.');
 else if(id==='battle-aftermath')dock=C('Aftermath pending','Whole-batch confirmation gate',true)+stock('132 / 220')+N('Confirm once','Only authority can declare the batch ready.')+B('Confirm aftermath (concept)','battle-fresh','primary');
 else if(id==='battle-fresh')dock=N('Aftermath confirmed','Fresh strategic intent is separate from finalization.','success')+B('Remain','fleet-orders')+B('Remain / seek combat','fleet-orders')+B('Move along known route','map-route')+B('Follow known contact','fleet-orders')+N('Terminal campaign?','If outcome is terminal, these actions are replaced by inspect/save only.');
 else if(id==='battle-no-survivors')dock=N('No owned survivors','Destroyed fleets cannot receive movement or follow orders.','error')+B('Return to campaign','map-sector','primary')+B('Save completed campaign','saves');
 else dock=C('Standing maneuver','Maintain distance · no preference')+`<div class="draft"><h3>Unsent round draft</h3>${field('Fleet maneuver','Screen',['Hold','Maintain distance','Charge','Flank','Screen'])}${field('Enemy-fleet preference',hidden?'No visible target':'Observed contact A',hidden?['No visible target']:['Observed contact A','Retain standing preference'])}<p class="copy small">Screen protects members of this fleet only. Targets are selected automatically.</p></div>`+B('Review round orders','battle-review','secondary')+B('Inspect own ship','battle-inspect')+N('Opening plan','Assembly spacing is a visual projection. Each strategic fleet remains one command unit.');
 if(terminalOutcome)dock=N('Campaign concluded','Retained condition and reports remain inspectable. No aftermath confirmation or fresh fleet order is available.','success')+B('Inspect retained report','battle-result')+B('Save completed campaign','saves','primary');
 return `<div class="layout three">${P('Fleets',rail)}${P(id==='battle-replay'?'3D result projection':'Central battle viewer',`<div class="battle-center">${view}<div>${report}</div></div>`,'',false)}${P(id==='battle-inspect'?'Selected ship':'Orders / condition',dock)}</div>`;
}
function modalPage(title,content,back,action,next='states'){window.MODAL_BACK=back;return `<div class="layout">${P('Current campaign',metrics()+N('Underlying state retained','Cancel, Escape and inspection do not dispatch a command.'))}${commonAside()}</div><div class="modal-veil"><section class="modal" role="dialog" aria-modal="true" aria-label="${title}"><h2>${title}</h2><div class="modal-scroll">${content}</div><div class="actions">${B('Cancel / keep current',back)}${B(action,next,'primary',id==='production-review')}</div><p class="small muted">Design interaction only · no campaign files or commands</p></section></div>`;}
function settings(){
 if(id==='save-confirm')return modalPage('Review save / action consequence',rows(['Selected slot','Demo1'],['Committed campaign','Turn9 · Planning'],['Local unsent edits','Not included'])+N('Confirm overwriting this slot','The previous compatible save is replaced only after successful atomic persistence.'),'saves','Confirm save (concept)','saves');
 if(id==='load-confirm')return modalPage(params.get('slot')==='demo-1'?'Load Demo1?':'Load Demo2?',rows(['Saved campaign',params.get('slot')==='demo-1'?'Turn9 · Victory':'Turn10 · Engineering mature'],['Current session','Retained until load succeeds'],['Unsent local changes','Discarded on successful replacement'])+N('One successful replacement','A failed load keeps your current host, accepted state and local drafts.'),'continue','Load selected (concept)','map-sector');
 if(id==='load-error')return `<div class="layout">${P('Load failed / current campaign retained',N('Profile mismatch','This slot belongs to a different campaign profile. It cannot be converted by this screen.','error')+C('Your current campaign remains open','Accepted state and local unsent draft are unchanged',true)+B('Choose a compatible slot','saves','primary')+B('Return to current campaign','map-sector'))}${P('Recover safely',rows(['Current slot','Unchanged'],['Current turn','Unchanged'],['Local draft','Retained'])+N('No silent fallback','Do not create a new campaign or load another slot automatically.'))}</div>`;
 if(id==='saves')return `<div class="layout">${P('Save and resume',C('Demo1','Turn9 · Victory · compatible current demo',true)+C('Demo2','Turn10 · Planning · compatible current demo')+C('Empty slot','No data')+N('Saved successfully','Committed campaign state saved. Unsent edits remain local and are not in the save.','success')+`<div class="actions">${B('Save current campaign','save-confirm','primary')}${B('Load selected','load-confirm?slot=demo-1')}</div>`+`<details><summary>Compatibility details</summary><p class="copy">Demo and frontier profiles have separate complete wrappers. No automatic migration is provided.</p></details>`)}${P('Persistence boundary',rows(['Selected slot','Demo1'],['Campaign profile','Explicit compatible profile'],['Failed load','Current session retained'])+B('View load-error state','load-error'))}</div>`;
 if(id.startsWith('audio'))return `<div class="layout">${P('Audio / device-local preferences',id==='audio-unavailable'?N('Audio service unavailable','Continue playing. Recover the service independently; settings do not block campaign navigation.','error'):N('Current music context','Deep Station / strategic background · existing accepted audio. No generation in this workflow.')+['Master','Music','Effects'].map((x,i)=>`<label class="field"><span>${x} ${[100,85,60][i]}%</span><input aria-label="${x} volume" type="range" min="0" max="100" value="${[100,85,60][i]}"></label><label><input type="checkbox"> Mute ${x.toLowerCase()}</label>`).join(''))}${P('Playback context',C('Context-sensitive music','Menu · strategic · combat',true)+N('Preferences stay local','Audio gain/mute is separate from campaign save state.')+B('Unavailable-service design','audio-unavailable'))}</div>`;
 if(id==='display')return `<div class="layout">${P('Display and accessibility',field('Application resolution','1920 ×1080',['1280 ×720','1920 ×1080','3440 ×1440'])+field('Window mode','Windowed',['Windowed','Borderless fullscreen'])+N('Application window only','These controls do not change the Windows desktop configuration.')+field('Text scale (proposed)','100%',['100%','115%','130%'])+field('Animation (proposed)','Reduced motion',['Reduced motion','Standard'])+N('Future accessibility controls','Scaling needs native layout/input acceptance; this browser proposal does not establish support.'))}${P('Interaction guidance',N('Keyboard / focus','Keep visible focus independent from selection. Modal Cancel/Confirm remain reachable; Escape keeps current state.')+B('Help & controls','help','primary')+B('Component state reference','states'))}</div>`;
 if(id==='help')return `<div class="layout">${P('How this campaign works',C('Strategic map','Pan/zoom inspect. Route preview does not move a fleet.',true,'map-route')+C('Fleet commands','One fleet remains one command unit; inspection is not firing.',false,'fleet-orders')+C('Battle rounds','Review → explicit commit → authoritative result → aftermath.',false,'battle-orders')+C('Construction and design','Only supported source revisions can be built.',false,'library')+N('Keyboard design guidance','Tab / ShiftTab focus; activate a focused control; Escape cancels supported dialogs. Actual game input acceptance remains a separate native test.'))}${commonAside()}</div>`;
 if(id==='notifications')return `<div class="layout">${P('Decisions and activity',C('Research prerequisite reached','Known own receipt · inspect eligible project',true,'engineering')+C('Fleet arrived','Arrival receipt; new public lanes only in frontier opt-in',false,'frontier')+C('Queue completed','Owned ship ready for strategic orders',false,'fleet')+C('Observed report stale','Reassess confidence; no hidden path prediction',false,'map-sensors')+future())}${commonAside()}</div>`;
 if(id==='diagnostics')return `<div class="layout">${P('Developer review utilities',N('Explicit developer context','Not a player ability. Single-player demo has no opponent actor switch.')+rows(['Save profile','Inspect own compatibility only'],['Refresh view','No authoritative mutation'],['Technical report','Actor-filtered only'])+B('Return to player interface','map-sector','primary'))}${P('Privacy gate',N('No omniscient host export','A host save carrier is never a player diagnostic/tooltip source.'))}</div>`;
 return `<div class="layout">${P('Shared visual state grammar',C('Selected','Amber leading edge + explicit label',true)+N('Unsent draft','Local edits are distinct from accepted intent.')+N('Accepted own receipt','Only your own confirmation is shown.','success')+N('Rejected / invalid','Retain the previous accepted state and local correction context.','error')+`<div class="actions">${B('Primary action','map-sector','primary')}${B('Unavailable / reason','','',true)}${B('Focused control','','secondary')}</div>`+N('Empty / busy','Explain the actual host operation. Never imply opponent readiness.'))}${P('Faction grammar',field('Theme',theme,['federation','klingon','cardassian','romulan','dominion'])+N('Shared workflow, distinct console','Klingon angular structure, Cardassian layered bronze, Romulan swept junctions, Dominion interlocked ribs. Full theme assets/typography remain proposals.')+B('Map interaction example','map-overview'))}</div>`;
}
function body(){
 const confirmations={
 'production-review':['Queue Cruiser at Earth?','production','120 credits +5 Dilithium ·16 Industry. Paid once; construction progresses during a supported Production phase.','Confirm queued construction'],
 'science-review':['Apply six-way Science allocation?','science','Review all six disciplines together. Current accepted allocation remains until the authority accepts this exact draft.','Apply Science draft'],
 'split-review':['Apply Science / Engineering split?','science','100% Science /0% Engineering. This is separate from discipline allocation and does not instantly develop technology.','Apply R&D split'],
 'strategic-review':['Submit fresh fleet order?','fleet-orders','Expedition fleet · move along known Sol–Bajor route. Actual route cost, ETA and stamped boundary must validate.','Submit strategic draft'],
 'cloak-review':['Apply fleet approach cloak?','fleet-cloak','Enable for capable members only. Incapable members remain visible; no stocks change and no mid-battle re-cloak.','Apply approach setting'],
 'designer-discard':['Discard local design changes?','designer','Unsaved local changes are abandoned. Published revisions, campaign hardware and current queues are unchanged.','Discard local draft'],
 'endturn-review':['Advance the strategic turn?','map-sector','Resolve accepted plans through authoritative weekly phases. Pending required battle/decision gates block advancement.','Confirm turn advance']};
 if(confirmations[id]){const [title,back,copy,action]=confirmations[id];return modalPage(title,(id==='production-review'?N('Insufficient treasury','116 credits available;120 required. Commitment unavailable.','error'):'')+N('Review consequence',copy)+rows(['Context','Fictional fixture'],['Accepted state','Retained until success']),back,action,back);}
 if(id==='setup-error')return `<div class="layout">${P('Generation could not be accepted',N('Validation failed','The proposed topology contains an unreachable starting region. Retain seed/settings for correction; no campaign was created.','error')+B('Adjust generation parameters','setup-galaxy','primary')+B('Return to setup','setup'))}${P('Retained setup',rows(['Seed','47281'],['Existing campaign','Unchanged'],['Failure details','Connectivity example only'])+future())}</div>`;
 if(id.startsWith('map-'))return mapPage();if(['Campaign'].includes(screen.family)||id==='setup-galaxy')return campaign();if(['Empire','Worlds'].includes(screen.family))return worlds();if(screen.family==='Production')return production();if(screen.family==='Fleets')return fleets();if(screen.family==='Research')return research();if(screen.family==='Designer')return designer();if(screen.family==='Exploration')return frontier();if(screen.family==='Expansion')return expansion();if(screen.family==='Diplomacy')return diplomacy();if(screen.family==='Battle')return battle();return settings();}
const preCampaign=['start','continue'].includes(id)||id.startsWith('setup');
 function footerAction(){
 if(preCampaign)return B('Review setup','setup-review','secondary');
 if(terminalOutcome)return B('Inspect / save only','saves','primary');
 if(id==='science')return B('Review Science allocation','science-review','primary');
 if(id==='battle-waiting')return B('Your order accepted','','primary',true);
 if(['battle-result','battle-reveal','battle-mutual'].includes(id))return B('Plan next round','battle-orders','primary');
 if(id==='battle-aftermath')return B('Confirm campaign aftermath','battle-fresh','primary');
 if(id==='battle-fresh')return B('Choose fresh strategic intent','fleet-orders','primary');
 if(id==='battle-no-survivors')return B('Return to campaign','map-sector','primary');
 if(id==='battle-replay')return B('Return to filtered report','battle-result','primary');
 if(id==='battle-lobby')return B('Resume selected battle','battle-orders','primary');
 if(screen.family==='Battle')return B('Review round orders','battle-review','primary');
 return B('Review turn','endturn-review','secondary');
 }
 document.querySelector('#app').classList.add('theme-'+theme);document.querySelector('#app').dataset.screen=id;
document.querySelector('#app').innerHTML=`<div class="concept-strip"><strong>DESIGN CONCEPT · FICTIONAL DATA</strong><span>Feature status ≠ implemented layout</span><select id="screen-picker" aria-label="Choose a mockup">${catalog.map(s=>`<option value="${s.id}" ${s.id===id?'selected':''}>${s.family} / ${s.title}</option>`).join('')}</select></div><header class="masthead"><div><div class="eyebrow">HobbyDS9 · ${theme} command</div><h1>${screen.title}</h1></div><div class="header-facts"><div><small>CAMPAIGN</small><b>${preCampaign?'Not started':terminalOutcome?terminalOutcome.toUpperCase():screen.family==='Battle'&&!['battle-fresh','battle-no-survivors'].includes(id)?'Battle pending':'Planning'}</b></div><div><small>TURN</small><b>${preCampaign?'—':'09'} <span class="muted">/ illustrative</span></b></div><div><small>CREDITS</small><b>${preCampaign?'—':'116'}</b></div></div></header><div class="workspace"><nav class="navigation" aria-label="Campaign navigation">${nav.map(([n,to])=>B(n,to,screen.family===n||screen.family==='Battle'&&n==='Battle'?'selected':'')).join('')}<div class="nav-divider">UTILITY</div>${B('Save / Load','saves')}${B('Settings','display')}${B('Help','help')}</nav><article class="page"><div class="scope-bar">${tag(screen.statusLabel,screen.status==='I'?'':'future')}<span>${screen.scope}</span></div>${body()}</article></div><footer class="bottom">${B(preCampaign?'‹ Campaign menu':'‹ Back to map',preCampaign?'start':'map-overview')}${B('Save','saves','quiet',preCampaign)}<span class="footer-note">${screen.family==='Battle'?'Fleet-level commands · cinematic camera has no authority':'Inspecting never submits · accepted state remains until explicit confirmation'}</span>${footerAction()}</footer>`;
function go(next){const [page,extra]=next.split('?');const query=new URLSearchParams(extra||'');query.set('screen',page);query.set('theme',theme);if(id==='load-confirm'&&page==='map-sector'){if(params.get('slot')==='demo-1')query.set('terminal','victory');}else if(terminalOutcome&&!['start','setup','setup-galaxy','setup-faction','setup-review'].includes(page))query.set('terminal',terminalOutcome);location.search=query.toString();}
