document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('[role="button"][data-go]'))go(e.target.dataset.go);if(e.key==='Escape'&&document.querySelector('.modal'))go(window.MODAL_BACK||'saves');});
