function buildMap(){
 const wrap=document.querySelector('.map-wrap');if(!wrap)return;
 let seed=Number(params.get('seed'))||47281;const random=()=>{seed=(Math.imul(1664525,seed)+1013904223)>>>0;return seed/4294967296;};
 const dense=wrap.dataset.dense==='true',full=wrap.dataset.full==='true',count=dense?130:full?Math.round(({Compact:58,Standard:96,Expansive:145}[params.get('size')]||58)*({Sparse:.7,Balanced:1,Dense:1.3}[params.get('density')]||1)):58;
 const points=[{x:195,y:300,name:'Sol'},{x:465,y:200,name:'Bajor'},{x:580,y:400,name:'Border transit'},{x:340,y:470,name:'Wormhole approach'}];
 let attempts=0;while(points.length<count&&attempts++<5000){const q={x:50+random()*900,y:75+random()*460,name:'Region '+String(points.length+1).padStart(2,'0')};if(full&&params.get('distribution')==='Spiral'){const a=points.length/count*Math.PI*6,r=45+Math.sqrt(random())*215;q.x=500+Math.cos(a)*r*1.8;q.y=310+Math.sin(a)*r;}if(points.every(p=>(p.x-q.x)**2+(p.y-q.y)**2>(dense?650:1700)))points.push(q);}
 const known=p=>full||p.x<665;
 function cell(site){let poly=[[10,45],[990,45],[990,565],[10,565]];for(const other of points.filter(known)){if(other===site)continue;const a=other.x-site.x,b=other.y-site.y,c=(other.x*other.x+other.y*other.y-site.x*site.x-site.y*site.y)/2;const out=[];for(let k=0;k<poly.length;k++){const p=poly[k],q=poly[(k+1)%poly.length],dp=a*p[0]+b*p[1]-c,dq=a*q[0]+b*q[1]-c;if(dp<=0)out.push(p);if((dp<=0)!==(dq<=0)){const f=dp/(dp-dq);out.push([p[0]+(q[0]-p[0])*f,p[1]+(q[1]-p[1])*f]);}}poly=out;if(!poly.length)break;}return poly.map(p=>p.map(n=>n.toFixed(1)).join(',')).join(' ');}
 const generationFailed=points.length<count;let markup='';if(['map-sensors','map-filters'].includes(id))markup+='<g class="sensor-layer"><rect x="0" y="45" width="440" height="520" fill="#5fbaad" opacity=".09"/><rect x="440" y="45" width="225" height="520" fill="#b99863" opacity=".08"/><text x="180" y="100" font-size="15" fill="#a4ceb3">CURRENT COVERAGE (CONCEPT)</text><text x="500" y="100" font-size="15" fill="#efb16b">STALE OBSERVATION</text></g><g class="lawful-contact-layer"><circle cx="580" cy="400" r="27" fill="none" stroke="#b9ace6" stroke-dasharray="5 5"/><text x="540" y="450" fill="#b9ace6" font-size="13">Last observed · no current track</text></g>';
 markup+=points.filter(known).map(p=>`<polygon points="${cell(p)}" fill="#1d3a5320" stroke="#607993" stroke-opacity=".28" stroke-width=".7" class="region-layer"/>`).join('');
 const links=new Set();points.forEach((p,i)=>{if(!known(p))return;const near=points.map((q,j)=>({j,d:(p.x-q.x)**2+(p.y-q.y)**2})).filter(v=>v.j!==i&&known(points[v.j])).sort((a,b)=>a.d-b.d).slice(0,2);near.forEach(({j})=>{let a=Math.min(i,j),b=Math.max(i,j),key=a+'-'+b;if(links.has(key))return;links.add(key);markup+=`<path d="M${p.x} ${p.y}L${points[j].x} ${points[j].y}" class="lane-layer" fill="none" stroke="#8dacc5" stroke-opacity=".4" stroke-width="1.2"/>`;});});
 markup+='<path class="lane-layer" d="M195 300L465 200" fill="none" stroke="#8dacc5" stroke-opacity=".6" stroke-width="1.5"/><path d="M340 470Q610 560 580 400" fill="none" stroke="#b9ace6" stroke-width="2" stroke-dasharray="7 5"/>';
 if(['map-route','map-travel'].includes(id))markup+='<path d="M195 300L465 200" fill="none" stroke="#efb16b" stroke-width="4" stroke-dasharray="9 5"/>';
 if(!full)markup+='<rect x="680" y="45" width="310" height="520" fill="#050b13" opacity=".91"/><text x="820" y="290" fill="#8192a6" font-size="20" text-anchor="middle">UNCHARTED</text><text x="820" y="320" fill="#8192a6" font-size="13" text-anchor="middle">No permitted route or contents</text>';
 markup+=points.filter(known).map((p,i)=>`<g class="star" role="button" tabindex="0" aria-label="Inspect known ${p.name}" data-node="${points.indexOf(p)}"><circle cx="${p.x}" cy="${p.y}" r="${i<4?7:4}" fill="${i===0?'#efb16b':'#b4daf3'}" stroke="#7a9fb8" stroke-width="1"/>${!dense||i<4?`<text x="${p.x+12}" y="${p.y+5}" font-size="${i<4?18:12}" fill="${i<4?'#eeeaf2':'#a9b8c8'}">${p.name}</text>`:''}</g>`).join('');
 if(!full)markup+='<g class="fleet-layer"><circle cx="195" cy="300" r="23" fill="none" stroke="#efb16b" stroke-width="2"/><text x="195" y="340" text-anchor="middle" fill="#efb16b" font-size="14">◎ Expedition ·3 own</text></g>';
 if(generationFailed)markup='<rect x="60" y="180" width="880" height="230" rx="14" fill="#311d29" stroke="#edaca7"/><text x="500" y="260" text-anchor="middle" font-size="26" fill="#edaca7">Generation proposal rejected</text><text x="500" y="310" text-anchor="middle" font-size="18" fill="#eeeaf2">Bounded placement attempt limit reached · settings retained</text><text x="500" y="345" text-anchor="middle" font-size="16" fill="#a9b8c8">Adjust density or seed. No campaign was created.</text>';
 const group=document.querySelector('#mapGroup');group.innerHTML=markup;if(generationFailed)document.querySelectorAll('[data-go="setup-review"]').forEach(b=>{b.disabled=true;b.title='Generation rejected: adjust seed/density before review';});
 const svg=wrap.querySelector('svg'),tip=wrap.querySelector('.map-tip');let scale=1,x=0,y=0,drag=null;
 const transform=()=>group.setAttribute('transform',`translate(${x} ${y}) scale(${scale})`);
 const select=n=>{const node=points[n];const context=document.querySelector('#selection-context');if(context)context.innerHTML=C('Selected sector: '+node.name,'Known navigation identity · fixture selection',true)+rows(['Knowledge','Charted public node'],['Body survey','Not inferred'],['Current fleet order','Remain'])+N('Selection only','Pinning a region does not submit a route or reveal adjacent unknown contents.')+B('Preview known route','map-route','primary');tip.hidden=true;};
 group.querySelectorAll('[data-node]').forEach(g=>{g.addEventListener('click',()=>select(+g.dataset.node));g.addEventListener('keydown',e=>{if(e.key==='Enter')select(+g.dataset.node);});g.addEventListener('pointerenter',()=>{tip.hidden=false;tip.textContent=points[+g.dataset.node].name+' · known node · select to pin';});g.addEventListener('pointerleave',()=>tip.hidden=true);});
 if(id==='map-sector'){group.insertAdjacentHTML('beforeend','<circle cx="465" cy="200" r="17" fill="none" stroke="#efb16b" stroke-width="3"/>');}
 if(id==='map-hover'){tip.hidden=false;tip.textContent='Bajor · known node · hover/focus is temporary; select to pin';}
 wrap.querySelectorAll('[data-map]').forEach(b=>b.addEventListener('click',()=>{if(b.dataset.map==='fit'){scale=1;x=0;y=0;}else scale=Math.max(.65,Math.min(3.5,scale*(b.dataset.map==='in'?1.2:1/1.2)));transform();}));
 svg.addEventListener('pointerdown',e=>{if(e.target.closest('[data-node]'))return;drag={x:e.clientX,y:e.clientY,tx:x,ty:y};svg.setPointerCapture(e.pointerId);});svg.addEventListener('pointermove',e=>{if(!drag)return;x=drag.tx+(e.clientX-drag.x)*1000/svg.clientWidth;y=drag.ty+(e.clientY-drag.y)*620/svg.clientHeight;transform();});svg.addEventListener('pointerup',()=>drag=null);
 svg.addEventListener('keydown',e=>{if(e.target!==svg)return;const delta={ArrowLeft:[30,0],ArrowRight:[-30,0],ArrowUp:[0,30],ArrowDown:[0,-30]}[e.key];if(delta){e.preventDefault();x+=delta[0];y+=delta[1];transform();}if(e.key==='Home'){x=0;y=0;scale=1;transform();}});
 svg.addEventListener('wheel',e=>{e.preventDefault();scale=Math.max(.65,Math.min(3.5,scale*(e.deltaY<0?1.1:1/1.1)));transform();},{passive:false});
 document.querySelector('[data-regenerate]')?.addEventListener('click',()=>{const input=document.querySelector('input[aria-label="Seed"]');const value=Number(input?.value)||47281;location.search=new URLSearchParams({screen:id,theme,seed:String(value),size:document.querySelector('select[aria-label="Size"]').value,density:document.querySelector('select[aria-label="Density"]').value,distribution:document.querySelector('select[aria-label="Distribution"]').value}).toString();});
 document.querySelector('[data-newseed]')?.addEventListener('click',()=>{const input=document.querySelector('input[aria-label="Seed"]');input.value=String((Number(input.value)||47281)+1);});
 document.querySelectorAll('[data-layer]').forEach((c,i)=>c.addEventListener('change',()=>{const selectors=['.lane-layer','.fleet-layer','.lawful-contact-layer','.sensor-layer','.region-layer','.star text'];group.querySelectorAll(selectors[i]).forEach(p=>p.style.opacity=c.checked?'1':'0');}));
 window.MAP_CONCEPT={seed:params.get('seed')||47281,points:points.filter(known).length,full,failure:generationFailed,attempts,generatedCount:full?points.length:undefined};
}
if(terminalOutcome){const blocked=new Set(['science-review','split-review','endturn-review','battle-review','production-review','production-cancel','strategic-review','cloak-review']);document.querySelectorAll('[data-go]').forEach(b=>{if(blocked.has(b.dataset.go)){b.disabled=true;b.title='Campaign concluded: inspection and saving only';}});document.querySelectorAll('.layout input,.layout select').forEach(e=>e.disabled=true);const bar=document.querySelector('.scope-bar');bar.insertAdjacentHTML('beforeend','<span class="tag amber">Campaign concluded · inspect / save only</span>');}
const modal=document.querySelector('.modal');if(modal){document.querySelectorAll('.navigation,.bottom,.masthead,.concept-strip,.page>.layout').forEach(e=>e.inert=true);modal.querySelector('button')?.focus();modal.addEventListener('keydown',e=>{if(e.key!=='Tab')return;const controls=[...modal.querySelectorAll('button,input,select,a[href]')].filter(x=>!x.disabled);if(!controls.length)return;e.preventDefault();const current=controls.indexOf(document.activeElement),next=(current+(e.shiftKey?-1:1)+controls.length)%controls.length;controls[next].focus();});}
let playback=null;const playButton=document.querySelector('[data-playback]');function play(){if(playback){clearInterval(playback);playback=null;playButton.textContent='Play';return;}playButton.textContent='Pause';playback=setInterval(()=>document.querySelector('[data-replay]').click(),1200/(Number(document.querySelector('[data-speed]').value)||1));}playButton?.addEventListener('click',play);document.querySelector('[data-speed]')?.addEventListener('change',()=>{if(playback){play();play();}});
